"OLAYLAR_ORTACAG_ORTADOGU:0711-07-26:0":{"b": ["Târık b. Ziyâd bringt dem westgotischen Heer eine schwere Niederlage bei", "73301b6a"], "d": ["Am Ende der acht Tage dauernden Schlacht zwischen den beiden Heeren erlitt das westgotische Heer eine schwere Niederlage (5 Şevval 92 / 26. Juli 711); der Schlachtort ist der Guadalete oder die Küste des Barbate. Es heißt, Târık habe in kurzer Zeit Málaga, Elvira, Córdoba und Toledo erobert.", "12d78ad9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0724-01-01:0":{"b": ["Hişâm b. Abdülmelik wurde Kalif (105/724); er regierte bis 743.", "6288b8a9"], "d": ["Hişâm b. Abdülmelik wurde Kalif (105/724); er regierte bis 743.", "6288b8a9"]},
"OLAYLAR_ORTACAG_ORTADOGU:0732-03-03:0":{"b": ["Das omaijadische Heer kämpfte bei Poitiers (Tours) gegen die Franken (114/732).", "97262cdf"], "d": ["Das omaijadische Heer kämpfte bei Poitiers (Tours) gegen die Franken (114/732).", "97262cdf"]},
"OLAYLAR_ORTACAG_ORTADOGU:0744-12-07:0":{"b": ["Mervân II. wurde zum Kalifen ausgerufen", "f51a800a"], "d": ["Die dort Anwesenden riefen Mervân zum Kalifen aus (26 Safer 127 / 7. Dezember 744); die Zeit des letzten omaijadischen Kalifen begann.", "1bc682b5"]},
"OLAYLAR_ORTACAG_ORTADOGU:0746-01-01:0":{"b": ["Mervân II. unterwirft Syrien; er lässt die Mauern von Homs, Baalbek, Damaskus und Jerusalem schleifen", "468a2d97"], "d": ["Mervân, der die Mauern der syrischen Städte schleifen ließ, um mögliche Aufstände zu verhindern, unterwarf Syrien im Sommer 128 (746).", "afc53641"]},
"OLAYLAR_ORTACAG_ORTADOGU:0747-01-01:0":{"b": ["Unter Führung Ebû Müslims begann in Chorasan offen die abbasidische Revolution (129/747).", "92a5194c"], "d": ["Unter Führung Ebû Müslims begann in Chorasan offen die abbasidische Revolution (129/747).", "92a5194c"]},
